                while ((match = regex.exec(blockStr)) !== null) {
                    var key = match[1].trim();
                    var val = match[2].trim();
                    roleData[key] = val;
                }

                if (Object.keys(roleData).length > 0) {
                    result.push(roleData);
                }
            });

            return result;
