                html += '      <span class="trk-value">' + location + '</span>';
                html += '    </div>';

                html += '    <div class="trk-row">';
                html += '      <span class="trk-label">🏃 动作</span>';
                html += '      <span class="trk-value">' + action + '</span>';
                html += '    </div>';

                html += '    <div class="trk-row">';
                html += '      <span class="trk-label">🎒 物品</span>';
                html += '      <span class="trk-value">' + items + '</span>';
