                html += '    </div>';

                html += '  </div>';
                html += '</div>';
            });

            container.innerHTML = html;
            bindToggleEvents(); // 渲染完成后绑定点击事件
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) return;

                var data = parseTrackerData(messageText);
                renderTracker(data);
            } catch (error) {
                document.getElementById('tracker-container').innerHTML =
                    '<div style="text-align:center; padding:10px; color:#d87083;">渲染出错: ' + error.message + '</div>';
            }
        }

        /* 启动 */
        $(function() { init(); });
    </script>
</body>
