        <!-- 商品列表容器 -->
        <div class="shop-body" id="shop-content-container">
            <div class="loading-text">正在扫描可用物资...</div>
        </div>
    </div>

    <script>
        /* ========== 1. 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) return null;
            return chatMessages[0].message;
        }

        /* ========== 2. 解析纯文本数据 ========== */
        function parseShopData(messageText) {
            var data = { categories: [] };
            var tagMatch = messageText.match(/<shop_panel>([\s\S]*?)<\/shop_panel>/);
            if (!tagMatch || !tagMatch[1]) return data;

            var lines = tagMatch[1].split('\n');
            var currentCategory = null;

            lines.forEach(function(line) {
                line = line.trim();
                if (!line) return;

                // 匹配分类 [Category|xxx]
                var catMatch = line.match(/\[Category\|(.*?)\]/);
                if (catMatch) {
                    currentCategory = {
                        id: 'cat_' + Math.random().toString(36).substr(2, 9), // 生成唯一ID用于Tab切换
                        name: catMatch[1].trim(),
                        items: []
                    };
                    data.categories.push(currentCategory);
                    return;
                }

                // 匹配商品 [Item|名称|价格|描述]
                var itemMatch = line.match(/\[Item\|(.*?)\|(.*?)\|(.*?)\]/);
                if (itemMatch && currentCategory) {
                    currentCategory.items.push({
                        name: itemMatch[1].trim(),
                        price: itemMatch[2].trim(),
                        desc: itemMatch[3].trim()
                    });
                }
            });

            return data;
        }

        /* ========== 3. 点击购买交互 ========== */
        window.handleBuyClick = function(itemName) {
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send 购买 ' + itemName);
            } else {
                console.warn("酒馆助手 triggerSlash 不可用");
            }
        };

        /* ========== 4. Tab切换逻辑 ========== */
        window.switchShopTab = function(categoryId) {
            // 移除所有Tab和Content的active类
            var tabs = document.querySelectorAll('.shop-tab');
            var contents = document.querySelectorAll('.shop-category');

            tabs.forEach(function(tab) { tab.classList.remove('active'); });
            contents.forEach(function(content) { content.classList.remove('active'); });

            // 为选中的Tab和对应的Content添加active类
            var selectedTab = document.getElementById('tab_' + categoryId);
            var selectedContent = document.getElementById('content_' + categoryId);

            if (selectedTab) selectedTab.classList.add('active');
            if (selectedContent) selectedContent.classList.add('active');
        };

        /* ========== 5. 渲染界面 ========== */
        function renderShop(data) {
            var tabsContainer = document.getElementById('shop-tabs-container');
            var contentContainer = document.getElementById('shop-content-container');

            if (!data.categories || data.categories.length === 0) {
                tabsContainer.innerHTML = '<span class="shop-tab">无数据</span>';
                contentContainer.innerHTML = '<div class="loading-text">当前区域无可用物资。</div>';
                return;
            }

            var tabsHtml = '';
            var contentHtml = '';
            var isFirst = true; // 标记第一个分类，用于默认激活

            data.categories.forEach(function(cat) {
                if (cat.items.length === 0) return;

                var activeClass = isFirst ? ' active' : '';

                // 渲染Tab按钮
                tabsHtml += '<span class="shop-tab' + activeClass + '" id="tab_' + cat.id + '" onclick="switchShopTab(\'' + cat.id + '\')">' + cat.name + '</span>';

                // 渲染对应分类的内容区
                contentHtml += '<div class="shop-category' + activeClass + '" id="content_' + cat.id + '">';

                cat.items.forEach(function(item) {
                    var safeName = item.name.replace(/'/g, "\\'").replace(/"/g, '&quot;');
                    contentHtml += '  <div class="shop-item">';
                    contentHtml += '    <div class="item-info">';
                    contentHtml += '      <span class="item-name">' + item.name + '</span>';
                    contentHtml += '      <span class="item-desc">' + item.desc + '</span>';
                    contentHtml += '    </div>';
                    contentHtml += '    <div class="item-action">';
                    contentHtml += '      <span class="item-price">' + item.price + '</span>';
                    contentHtml += '      <button class="buy-btn" onclick="handleBuyClick(\'' + safeName + '\')">获取</button>';
                    contentHtml += '    </div>';
                    contentHtml += '  </div>';
                });

                contentHtml += '</div>';
                isFirst = false; // 只有第一个分类会默认激活
            });

            if (tabsHtml === '') {
                tabsContainer.innerHTML = '<span class="shop-tab">无数据</span>';
                contentContainer.innerHTML = '<div class="loading-text">物资列表解析失败或为空。</div>';
            } else {
                tabsContainer.innerHTML = tabsHtml;
                contentContainer.innerHTML = contentHtml;
            }
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) return;

                var data = parseShopData(messageText);
                renderShop(data);
            } catch (error) {
                document.getElementById('shop-content-container').innerHTML =
                    '<div class="loading-text">系统故障: ' + error.message + '</div>';
            }
        }

        /* 启动 */
        if (typeof $ !== 'undefined') {
            $(function() { init(); });
        } else {
            window.onload = init;
        }
    </script>
</body>
</html>
